/* ----------------------------------------------------------------------------
   派生的"空气透视"配色
   ----------------------------------------------------------------------------
   手写的 sky/hill/grass/wood 只够分物件，分不出**前后**。

   上一版的远山直接用了主题里的 hill1/hill2 —— 那对颜色是从草地色派生的，
   和天空同明度同色相（泥沼那关：暖黄天空 + 黄褐山），画上去等于没有，
   整片背景读作"一块渐变色板"。这就是用户说的"像画出来的"。

   空气透视的正解是**色相分离 + 明度递进**，两条都用程序算，八套主题自动一致：
     · 远的往冷里走（混青蓝），近的回到草色 —— 色相上就分开了；
     · 远的往天空里混得多（更亮更淡），近的混得少（更实）—— 明度上再分一次。
   -------------------------------------------------------------------------- */

/* 草地整体压暗的系数。
   0.86 → 0.80 是在换成暖金天空之后调的：亮黄绿的草地 + 暖金天空，
   两者明度太接近，平台的投影读不出来，整屏像"一张金绿色的纸"。
   压到 0.80 之后草退到中景，木平台和角色的明度才跳出来。
   **只压 grass / grass2** —— 压暗 sky / wood 会把纵深反着压平。 */
const GRASS_DIM = 0.80;

/* 雪地的地面压暗系数。**雪是唯一不能按 0.80 压的主题。**
   0.80 的 #D6E3F2 会变成 #ABB6C2 —— 一块冷灰水泥，不是雪。
   0.90 之后明度约 205，仍比压过的草地（约 130）亮 75 档，
   角色分离靠描边和木平台的暖色，不靠把地面压黑。
   **只给雪地开这个口子**，其它七套一律 0.80 —— 否则会变成
   "每关都能找到一个理由调参数"，八套就不成一套系统了。 */
const SNOW_DIM = 0.90;

function hexDim(hex, k) {
  const n = parseInt(hex.slice(1), 16);
  const r = Math.min(255, Math.round(((n >> 16) & 255) * k));
  const g2 = Math.min(255, Math.round(((n >> 8) & 255) * k));
  const b = Math.min(255, Math.round((n & 255) * k));
  return "#" + ((1 << 24) | (r << 16) | (g2 << 8) | b).toString(16).slice(1);
}

/** t = 0 → a，t = 1 → b */
function hexMix(a, b, t) {
  const na = parseInt(a.slice(1), 16), nb = parseInt(b.slice(1), 16);
  const ch = (s) => {
    const va = (na >> s) & 255, vb = (nb >> s) & 255;
    return Math.min(255, Math.max(0, Math.round(va * (1 - t) + vb * t)));
  };
  return "#" + ((1 << 24) | (ch(16) << 16) | (ch(8) << 8) | ch(0)).toString(16).slice(1);
}

/** 同一个颜色、指定的 alpha。做雾带时必须用它 ——
 *  从 #RRGGBB 渐变到 rgba(0,0,0,0)，中间会插出灰黑，雾会变脏。 */
function rgbaOf(hex, a) {
  const n = parseInt(hex.slice(1), 16);
  return "rgba(" + ((n >> 16) & 255) + "," + ((n >> 8) & 255) + "," + (n & 255) + "," + a + ")";
}

/* 远景的统一冷调。偏青蓝，但不能太蓝（太蓝会像阴天，和"Q 版亮天空"冲突）。 */
const COOL = "#5F86A8";

/** 前景剪影用的墨绿。**刻意保留一点绿**，纯黑("#000")会在低亮屏幕上糊成一块洞；
 *  带一点点绿，它仍然是"叶子"，只是逆光。 */
const INK_LEAF = "#14241A";

for (const _tk of Object.keys(THEMES)) {
  const T = THEMES[_tk];

  /* 草地压一档 + 明度纵深三档
     原来草地 L≈70、我方主体 L≈55，只差一档 —— 灰度下猫和草地糊在一起。
     压 0.86 约等于 L 降 8，主体就跳出来了。
     **只压 grass / grass2，不动 sky / hill / wood**：远山要"淡"（往天空靠），
     平台要"靠描边和投影分离"，压暗它们只会把层次压平。
     压同一个系数，草皮亮面与草地底色的相对关系不变 ——
     两个色各压各的，草皮的"受光"会消失，地面就变成一块平涂。 */
  const gdim = T.snow ? SNOW_DIM : GRASS_DIM;
  T.grass2 = hexDim(T.grass2, gdim);
  T.grass = hexDim(T.grass, gdim);

  /* ---------------- 木材锁定 ----------------
     八关八套主题，但**木头只有一种**。

     原来 wood / wood2 / wood3 跟着主题整组换色相：第 8 关（紫夜）是
     "#8E80CA / #6A5E9E / #C8BEF2"，画出来是**一排紫色胶囊**。
     玩家不会读成"被紫光照着的木板"，只会读成"这不是木头" ——
     这是常识违反，不是风格选择，和"树画成橙色"是同一类错。

     概念图里环境是冷的（背光的蓝绿林荫），人造物是暖的（橙木台），
     靠这个冷暖对立把"能站的地方"从背景里推出来。
     所以木头锁在暖棕，主题只决定**被什么光照着**：
     主题原木色只留 16% 的倾向，冷关偏灰紫、暖关偏橙。

     明度还要跟环境走一档：夜里（天空暗）木头要沉下去，
     否则紫夜关一排暖橙木板会亮得像贴了荧光条。 */
  const WB3 = "#E6C08A";   // 顶面受光
  const WB1 = "#BC8049";   // 顶面主色
  const WB2 = "#7C5029";   // 侧面暗部
  /* 主题只留 22%。再高（试过 0.45）第 8 关又会读出紫色胶囊；
     再低（0.10）八关看起来是同一张图，关与关之间没有温差。 */
  const tint = hexMix(WB1, T.wood, 0.22);
  const skyL = (parseInt(T.sky1.slice(1, 3), 16) * 0.3 +
                parseInt(T.sky1.slice(3, 5), 16) * 0.59 +
                parseInt(T.sky1.slice(5, 7), 16) * 0.11) / 255;
  /* 0.86（夜）~ 1.0（白天）。0.86 是下限：再压木头的板缝就消失了，
     而板缝正是"这是堆叠木板"唯一的证据。 */
  const ambL = 0.86 + 0.14 * Math.min(1, skyL * 1.9);
  T.wood3 = hexDim(hexMix(WB3, tint, 0.30), ambL);
  T.wood = hexDim(tint, ambL);
  T.wood2 = hexDim(hexMix(WB2, tint, 0.34), ambL);

  /* 地面自己也要有纵深：地平线附近发亮（远处受天光照）、画面底部最暗。 */
  const cooled = hexMix(T.grass, COOL, 0.24);
  T.grassLight = hexMix(T.grass2, T.sky2, 0.30);
  T.grassDark = hexDim(T.grass, 0.74);

  /* 远山两档：远的混天空多（更淡），近的混草色多（更实）。
   *
   * 0.48 / 0.72 不是 0.24 / 0.50 —— 混得太少的话山几乎等于天空色，
   * 在暖色主题上（第 4 关：橙黄天空）整片远山直接消失，画面只剩"天 + 地"两块。
   * 空气透视不是"把远山变淡到看不见"，是"变淡但仍能分出三段明度"。 */
  T.hillFar = hexMix(T.sky2, cooled, 0.48);
  T.hillNear = hexMix(T.sky2, cooled, 0.72);
  /* 地平线雾带：天空色里渗一点点草绿，读作"远处的空气"。 */
  T.horizon = hexMix(T.sky2, cooled, 0.14);

  /* 树：近景树和草地同族但更亮，远景树退到远山那一档。
   *
   * **但要往叶绿锚一点（0.30）。** 八关八套色，其中第 4 关（slope）是纯暖橙：
   * 草 "#D9764A"、木 "#C4703E"、山 "#E08A5E"。树的颜色原来完全从草派生，
   * 于是那一关的树是橙褐色的 —— 和山坡、木头同一个色相，光看轮廓读不出"这是树"，
   * 读成"一块鼓包"。
   * 混 0.30 的叶绿之后，暖色关里它是橄榄绿：仍然在这个关的色域里（不跳），
   * 但有"活的东西"这个读法。晚上、紫夜关同理，只会更沉，不会更艳。 */
  const LEAF = "#6FB33F";
  /* 树要**压暗**（0.74），不能跟草地一样亮。
     0.97 的时候近景树和草地同明度，只在轮廓上分开 ——
     换成暖金天空之后更糟：树冠在天空前是一团发亮的浅黄绿，
     读作"天上挂了两个浅色球"。概念图里近景树是深色剪影，
     亮的那一侧靠边缘的暖光，不靠整体提亮。 */
  T.treeNear = hexDim(hexMix(hexMix(T.grass2, LEAF, 0.30), "#FFFFFF", 0.05), 0.74);
  T.treeFar = hexMix(T.treeNear, T.hillFar, 0.28);

  /* 雪地的树**不能从雪面派生**。
     上面的通用算法是 mix(grass2, LEAF) —— 雪地的 grass2 近白，混出的是淡绿白，
     压 0.74 之后是灰绿，读作"一棵掉漆的树"。雪松本来就是深色的：
     **雪压枝头不等于树变白**（这一点和雪面不能压暗是同一条逻辑的反面）。
     压 0.92 而不是 0.74 —— 雪地背景整体亮，树要压得更沉才有剪影；
     远景树混远山的比例也从 0.28 拉到 0.52，让它在雪雾里退得更快。 */
  if (T.snow) {
    T.treeNear = hexDim("#2E5B4A", 0.92);
    /* 远景树混 0.72（通用是 0.28、第一版给雪地也是 0.52）。
       0.52 出来是灰绿的一片，在雪雾里读作"雾霾"而不是"远处的树林" ——
       雪景的远景树几乎只剩蓝灰轮廓，绿色早被雪和空气吃掉了。 */
    T.treeFar = hexMix(T.treeNear, T.hillFar, 0.72);
  }

  T.trunkNear = hexDim(T.wood2, 0.86);
  T.trunkFar = hexMix(T.trunkNear, T.hillFar, 0.45);

  /* 前景灌木：**压到接近剪影**，不只是"暗一档"。
     0.54 出来的是"深绿灌木"—— 它和草地暗部同族，读作"地上长得比较深的草"，
     撑着画面的力气不够。概念图里这一层几乎是黑的（#1E2A1A 级别），
     才把视线从画面边缘推进中场。

     混的色也不能是 COOL（偏青蓝）：青蓝前景压在绿草上会发灰，
     读作"没上色的草"。改混近黑的墨绿 INK_LEAF，压完是暖调的暗，
     和暖金天空、橙木平台在同一色温上。 */
  /* 剪影是"**深**"，不是"黑"。
     0.66 混 + 0.52 压之后，第 1 关（暖金天空、亮绿草地）出来是一整条
     近乎纯黑的带子 —— 读作"画面被黑边切掉一截"，读不出"这是草"。
     混 0.54、压 0.70：仍然是画面里最暗的一层，但看得出是绿、是叶子。
     受光边也提一档（0.22 → 0.34），否则一丛里几片叶子分不出来，只是黑球。 */
  T.shrub = hexDim(hexMix(T.grass, INK_LEAF, 0.54), 0.70);
  T.shrubLit = hexMix(T.shrub, "#FFE9B8", 0.34);

  /* ---------------- 雪地：四处覆写 ----------------
     上面所有派生都建立在「草是绿的、土地是褐的」这个前提上。雪地一条都不成立，
     所以不是调参数能解决的 —— 必须按"雪"的物理重算。

     **集中写在循环末尾一处**，不散到各自的算法里：八套主题共用一套派生流程，
     雪地是唯一的例外分支，例外越集中越不容易在下一次改动时漏掉。

     ① 远山：通用是 mix(sky2, cooled)，雪地 sky2 与 grass 都近白 → 混出白，
        远山整片消失。雪景的纵深**全靠远山那点冷蓝**，所以直接锁蓝灰。
     ② 地平线雾带同理，混一个淡蓝才有"远处空气"。
     ③ 地面最暗档：通用 hexDim(grass, 0.74) 把雪压成 #9EA6B2 —— 一块沥青路面。
        雪的"暗部"是**背光的雪**，是蓝的、不是灰的。改成压得极轻再混冷蓝。
     ④ 前景灌木：通用是把草地混墨绿压暗 → 深绿灌木。雪地里长深绿灌木丛
        读作"没扫干净的落叶"。改成冷白 —— 形状语言现成的，白色就是雪堆。
        **受光边保持最亮**，否则雪堆会糊成一个白团。 */
  if (T.snow) {
    T.hillFar = hexMix(T.sky2, "#7E9BBE", 0.42);
    T.hillNear = hexMix(T.sky2, "#6C8CB2", 0.62);
    T.horizon = hexMix(T.sky2, "#C8D8EA", 0.50);
    T.grassDark = hexMix(hexDim(T.grass, 0.92), "#8FA6C4", 0.38);
    T.shrub = hexMix("#DCE8F6", "#93AACB", 0.42);
    T.shrubLit = "#F4FAFF";
  }
}

